// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockNum) public {
        bound(blockNum, 1, 1e6);
        vm.roll(blockNum);
        vm.warp(1);
        address caller = makeAddr("caller");
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        if (blockNum % 15 == 0) {
            assertEq(address(c).balance, 0);
        } else {
            assertTrue(address(c).balance > 0);
        }
    }
}
